    {
      json: {
        ...base,
        shouldProcess: false,
        requestFailed: true,
        failureStage,
        errorMessage: clean(errorMessage, 900),
        slackNotificationAllowed: Boolean(env('SLACK_BOT_TOKEN') && env('SLACK_CHANNEL_ID')),
