const item = $input.first();
const rawBody = rawBodyFrom(item);
let body;
try {
  body = parseBody(item, rawBody);
} catch (error) {
  return [
    {
      json: {
        ackStatusCode: 400,
        ackText: 'invalid json',
        shouldProcess: false,
        requestFailed: false,
        ignored: true,
        ignoreReason: 'invalid_json',
      },
    },
  ];
}

if (String(env('FIGMA_WEBHOOK_ENABLED') || 'false').toLowerCase() !== 'true') {
  return [
    {
      json: {
        ackStatusCode: 200,
        ackText: 'figma webhook disabled',
        shouldProcess: false,
        requestFailed: false,
        ignored: true,
        ignoreReason: 'figma_webhook_disabled',
      },
    },
  ];
}

const configuredPasscode = env('FIGMA_WEBHOOK_PASSCODE');
if (!configuredPasscode) {
  return [
    {
      json: {
        ackStatusCode: 500,
        ackText: 'figma webhook passcode is not configured',
        shouldProcess: false,
        requestFailed: false,
        ignored: true,
        ignoreReason: 'missing_figma_webhook_passcode',
      },
    },
  ];
}

if (!safeCompare(configuredPasscode, body.passcode)) {
  console.log(JSON.stringify({ stage: 'FIGMA_WEBHOOK_REJECTED', reason: 'invalid_passcode' }));
  return [
    {
      json: {
        ackStatusCode: 403,
        ackText: 'forbidden',
        shouldProcess: false,
        requestFailed: false,
        ignored: true,
        ignoreReason: 'invalid_passcode',
      },
    },
  ];
}

if (body.event_type === 'PING') {
  console.log(JSON.stringify({ stage: 'FIGMA_WEBHOOK_RECEIVED', eventType: 'PING', accepted: false }));
  return [
    {
      json: {
        ackStatusCode: 200,
        ackText: 'ok',
        shouldProcess: false,
        requestFailed: false,
        ignored: true,
        ignoreReason: 'ping',
      },
    },
  ];
}

const base = {
  ackStatusCode: 200,
  ackText: 'ok',
  eventType: clean(body.event_type, 80),
  figmaMakeFileKey: clean(body.file_key, 200),
  figmaFileName: clean(body.file_name, 500),
  figmaVersionId: clean(body.version_id, 200),
  figmaVersionLabel: clean(body.label, 500),
  figmaVersionDescription: clean(body.description, 2000),
  figmaVersionCreatedAt: clean(body.created_at || body.timestamp, 100),
  figmaWebhookTimestamp: clean(body.timestamp, 100),
  figmaWebhookId: clean(body.webhook_id, 100),
  figmaTriggeredBy: body.triggered_by || null,
  slackChannelId: env('SLACK_CHANNEL_ID') || '',
};

console.log(
  JSON.stringify({
    stage: 'FIGMA_WEBHOOK_RECEIVED',
    eventType: base.eventType,
    fileKey: base.figmaMakeFileKey,
    versionId: base.figmaVersionId,
  }),
);

if (base.eventType !== 'FILE_VERSION_UPDATE') {
  return [{ json: { ...base, shouldProcess: false, requestFailed: false, ignored: true, ignoreReason: 'wrong_event_type' } }];
}

if (!base.figmaMakeFileKey || !base.figmaVersionId) {
  return failBeforeClaude(base, 'FIGMA_WEBHOOK_VALIDATE', 'Figma FILE_VERSION_UPDATE payload is missing file_key or version_id.');
}

const jiraProjectKey = env('JIRA_PROJECT_KEY') || 'SYSCO';
const issuePattern = new RegExp(`\\b${jiraProjectKey.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}-\\d+\\b`, 'i');
const versionText = `${base.figmaVersionLabel}\n${base.figmaVersionDescription}`;
const issueMatch = versionText.match(issuePattern);
if (!issueMatch) {
  return failBeforeClaude(
    base,
    'JIRA_KEY_PARSE',
    `No ${jiraProjectKey}-<number> Jira issue key was found in the Figma version label or description.`,
  );
}

const jiraIssueKey = issueMatch[0].toUpperCase();
const handoffId = `${base.figmaMakeFileKey}:${base.figmaVersionId}`;
const correlationId = makeCorrelation(jiraIssueKey, base.figmaMakeFileKey, base.figmaVersionId);
const now = Date.now();
const nowIso = new Date(now).toISOString();
const staticData = $getWorkflowStaticData('global');
staticData.figmaHandoffs = staticData.figmaHandoffs || {};
staticData.figmaDesignMappings = staticData.figmaDesignMappings || {};
pruneHandoffs(staticData.figmaHandoffs, now);

const existing = staticData.figmaHandoffs[handoffId];
if (existing?.status === 'completed') {
  console.log(JSON.stringify({ stage: 'FIGMA_VERSION_DUPLICATE', handoffId, status: existing.status, correlationId }));
  return [
    {
      json: {
        ...base,
        jiraIssueKey,
        handoffId,
        correlationId,
        shouldProcess: false,
        requestFailed: false,
        ignored: true,
        ignoreReason: 'duplicate_completed_handoff',
        duplicate: true,
      },
    },
  ];
}

const processingStatuses = new Set(['processing', 'figma_source_resolved', 'claude_started', 'figma_processing']);
if (processingStatuses.has(existing?.status)) {
  const updatedAt = Date.parse(existing.updatedAt || existing.createdAt || '');
  if (Number.isFinite(updatedAt) && now - updatedAt < 4 * 60 * 60 * 1000) {
    console.log(JSON.stringify({ stage: 'FIGMA_VERSION_DUPLICATE', handoffId, status: existing.status, correlationId }));
    return [
      {
        json: {
          ...base,
          jiraIssueKey,
          handoffId,
          correlationId,
          shouldProcess: false,
          requestFailed: false,
          ignored: true,
          ignoreReason: 'duplicate_processing_handoff',
          duplicate: true,
        },
      },
    ];
  }
}

if (existing?.status === 'jira_failed' && existing.design?.url) {
  console.log(JSON.stringify({ stage: 'FIGMA_VERSION_RETRY_JIRA', handoffId, correlationId }));
  return [
    {
      json: {
        ...base,
        jiraIssueKey,
        handoffId,
        correlationId: existing.correlationId || correlationId,
        shouldProcess: true,
        retryJiraOnly: true,
        requestFailed: false,
        slackChannelId: existing.slack?.channel || base.slackChannelId,
        slackThreadTs: existing.slack?.threadTs || '',
        figmaReady: true,
        claudeSuccess: true,
        design: existing.design,
        figmaDesignUrl: existing.design.url,
        figmaDesignFileKey: existing.design.fileKey || '',
        figmaDesignNodeId: existing.design.nodeId || '',
      },
    },
  ];
}

staticData.figmaHandoffs[handoffId] = {
  status: 'processing',
  createdAt: existing?.createdAt || nowIso,
  updatedAt: nowIso,
  correlationId,
  jiraIssueKey,
  source: {
    figmaMakeFileKey: base.figmaMakeFileKey,
    figmaVersionId: base.figmaVersionId,
    figmaVersionLabel: base.figmaVersionLabel,
    figmaVersionDescription: base.figmaVersionDescription,
  },
};

console.log(JSON.stringify({ stage: 'VERSION_ACCEPTED', handoffId, correlationId, jiraIssueKey }));

return [
  {
    json: {
      ...base,
      jiraIssueKey,
      handoffId,
      correlationId,
      shouldProcess: true,
      retryJiraOnly: false,
      requestFailed: false,
      ignored: false,
    },
  },
];

const env = (name) => $env[name];
const https = require('https');
const http = require('http');

function requiredEnv(names) {
  const missing = names.filter((name) => !env(name));
  if (missing.length) throw new Error(`Missing environment variable(s): ${missing.join(', ')}`);
}

function adfToText(node) {
  if (!node) return '';
  if (typeof node === 'string') return node;
  if (Array.isArray(node)) return node.map(adfToText).filter(Boolean).join('\n');
  if (node.type === 'text') return node.text || '';
  if (Array.isArray(node.content)) return node.content.map(adfToText).filter(Boolean).join(node.type === 'paragraph' ? ' ' : '\n');
  return '';
}

async function jiraFetch(path, options = {}) {
  const baseUrl = env('JIRA_BASE_URL').replace(/\/$/, '');
  const response = await httpRequest(`${baseUrl}${path}`, {
    method: options.method || 'GET',
    headers: {
      Authorization: env('JIRA_AUTH_HEADER'),
      Accept: 'application/json',
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    body: options.body,
  });

  const text = response.bodyText;
  let data = {};
  if (text) {
    try {
      data = JSON.parse(text);
    } catch {
      data = { raw: text.slice(0, 600) };
    }
  }

  if (!response.ok) {
    const error = new Error(`Jira ${options.method || 'GET'} ${path} failed (${response.status}): ${text.slice(0, 600)}`);
    error.status = response.status;
    error.data = data;
    throw error;
  }
  return data;
}

async function httpRequest(url, options = {}) {
  if (typeof fetch === 'function') {
    const response = await fetch(url, options);
    return {
      status: response.status,
      ok: response.ok,
      bodyText: await response.text(),
    };
  }

  const method = options.method || 'GET';
  const body = options.body || '';
  const headers = { ...(options.headers || {}) };
  if (body && !headers['Content-Length']) headers['Content-Length'] = Buffer.byteLength(body);
  const client = url.startsWith('https:') ? https : http;

  return await new Promise((resolve, reject) => {
    const request = client.request(url, { method, headers }, (response) => {
      const chunks = [];
      response.on('data', (chunk) => chunks.push(Buffer.from(chunk)));
      response.on('end', () => {
        const status = response.statusCode || 0;
        resolve({
          status,
          ok: status >= 200 && status < 300,
          bodyText: Buffer.concat(chunks).toString('utf8'),
        });
      });
    });
    request.on('error', reject);
    request.setTimeout(30000, () => request.destroy(new Error(`HTTP ${method} ${url} timed out`)));
    if (body) request.write(body);
    request.end();
  });
}

function markHandoff(handoffId, patch) {
  if (!handoffId) return;
  const staticData = $getWorkflowStaticData('global');
  staticData.figmaHandoffs = staticData.figmaHandoffs || {};
  staticData.figmaHandoffs[handoffId] = {
    ...(staticData.figmaHandoffs[handoffId] || {}),
    ...patch,
    updatedAt: new Date().toISOString(),
  };
}

const input = $input.first().json;
if ((!input.shouldProcess && !input.retryJiraOnly) || input.requestFailed) return [{ json: input }];

let failureStage = 'JIRA_VALIDATED';
try {
  requiredEnv(['JIRA_BASE_URL', 'JIRA_PROJECT_KEY', 'JIRA_AUTH_HEADER']);
  const projectKey = env('JIRA_PROJECT_KEY');
  const issueKey = String(input.jiraIssueKey || '').toUpperCase();
  if (!new RegExp(`^${projectKey}-\\d+$`, 'i').test(issueKey)) {
    throw new Error(`Issue ${issueKey || '(missing)'} is outside configured project ${projectKey}.`);
  }

  const issue = await jiraFetch(`/rest/api/3/issue/${encodeURIComponent(issueKey)}?fields=summary,description,status,issuetype,priority`);
  const jiraIssueUrl = `${env('JIRA_BASE_URL').replace(/\/$/, '')}/browse/${issueKey}`;
  const jiraSummary = issue.fields?.summary || issueKey;
  const jiraDescriptionText = adfToText(issue.fields?.description).slice(0, 6000);

  markHandoff(input.handoffId, {
    status: input.retryJiraOnly ? 'jira_retrying' : 'jira_verified',
    jiraIssueKey: issueKey,
    jiraIssueUrl,
  });

  console.log(JSON.stringify({ stage: 'JIRA_VALIDATED', correlationId: input.correlationId, jiraIssueKey: issueKey }));

  return [
    {
      json: {
        ...input,
        jiraOk: true,
        jiraIssueKey: issueKey,
        jiraIssueUrl,
        jiraSummary,
        jiraDescriptionText,
        jiraStatus: issue.fields?.status?.name || '',
      },
    },
  ];
} catch (error) {
  const errorMessage = String(error.message || error).slice(0, 900);
  markHandoff(input.handoffId, {
    status: 'failed',
    failureStage,
    errorMessage,
  });
  return [
    {
      json: {
        ...input,
        shouldProcess: false,
        requestFailed: true,
        failureStage,
        errorMessage,
        jiraIssueUrl: input.jiraIssueKey ? `${env('JIRA_BASE_URL')?.replace(/\/$/, '') || ''}/browse/${input.jiraIssueKey}` : '',
        slackNotificationAllowed: Boolean(env('SLACK_BOT_TOKEN') && env('SLACK_CHANNEL_ID')),
      },
    },
  ];
}

const env = (name) => $env[name];
const https = require('https');
const http = require('http');

async function postSlack(payload) {
  const response = await httpRequest('https://slack.com/api/chat.postMessage', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${env('SLACK_BOT_TOKEN')}`,
      'Content-Type': 'application/json; charset=utf-8',
    },
    body: JSON.stringify({
      unfurl_links: false,
      unfurl_media: false,
      ...payload,
    }),
  });
  const data = response.bodyText ? JSON.parse(response.bodyText) : {};
  if (!data.ok) throw new Error(`Slack chat.postMessage failed: ${data.error || 'unknown_error'}`);
  return data;
}

async function httpRequest(url, options = {}) {
  if (typeof fetch === 'function') {
    const response = await fetch(url, options);
    return {
      status: response.status,
      ok: response.ok,
      bodyText: await response.text(),
    };
  }

  const method = options.method || 'GET';
  const body = options.body || '';
  const headers = { ...(options.headers || {}) };
  if (body && !headers['Content-Length']) headers['Content-Length'] = Buffer.byteLength(body);
  const client = url.startsWith('https:') ? https : http;

  return await new Promise((resolve, reject) => {
    const request = client.request(url, { method, headers }, (response) => {
      const chunks = [];
      response.on('data', (chunk) => chunks.push(Buffer.from(chunk)));
      response.on('end', () => {
        const status = response.statusCode || 0;
        resolve({
          status,
          ok: status >= 200 && status < 300,
          bodyText: Buffer.concat(chunks).toString('utf8'),
        });
      });
